"""Audio-first AR catch-up ladder: small numbers, spoken mental-math questions, answers said as a number.
Every item carries `check`, a sympy expression written straight from the question, which build/validate.py re-evaluates."""
import random
from math import gcd
from fractions import Fraction as F
DW = {2:('half','halves'),3:('third','thirds'),4:('fourth','fourths'),5:('fifth','fifths'),6:('sixth','sixths'),7:('seventh','sevenths'),
      8:('eighth','eighths'),9:('ninth','ninths'),10:('tenth','tenths'),12:('twelfth','twelfths')}
def fw(v):   # spoken words for a fraction / mixed number
    v = F(v)
    if v.denominator == 1: return str(v.numerator)
    if v < 0: return 'negative ' + fw(-v)
    w, p = divmod(v.numerator, v.denominator); d = v.denominator; n = p
    s = f"{n} {DW[d][0] if n == 1 else DW[d][1]}" if d in DW else f"{n} over {d}"
    return f"{w} and {s}" if w else s
def fs(v, mixed=True):
    v = F(v)
    if v.denominator == 1: return str(v.numerator)
    if v < 0: return '-' + fs(-v, mixed)
    w, p = divmod(v.numerator, v.denominator)
    return f"{w} {p}/{v.denominator}" if (w and mixed) else f"{v.numerator}/{v.denominator}"
def money(v):
    v = F(v); return f"${v.numerator // v.denominator}" if v.denominator == 1 else f"${float(v):.2f}"
def dec(v):
    v = F(v); x = float(v); return str(int(x)) if x == int(x) else ('%.3f' % x).rstrip('0').rstrip('.')
R = lambda n, d=1: f"Rational({n},{d})"
FMT = {'num': lambda v: fs(v), 'frac': lambda v: fs(v), 'improper': lambda v: fs(v, False), 'money': money, 'dec': dec, 'pct': lambda v: f"{fs(v)}%"}
def item(stem, ans, wrong, steps, check, kind='num', form=None, mode='say', say=None, unit=''):
    return dict(stem=stem, ans=F(ans), wrong=[F(w) for w in wrong], steps=steps, check=check, kind=kind, form=form, mode=mode, say=say, unit=unit)
def near(v, r, k=3, pos=True):
    v = F(v); c = [v + 1, v - 1, v + 2, v * 2, v - 2, v + 10, v + F(1, 2) if v.denominator == 1 else v + 1, v * 3 if v else 3]
    out = []
    for x in c:
        if x != v and x not in out and (not pos or x > 0): out.append(x)
    r.shuffle(out); return out[:k]
NM = ['Ana', 'Ben', 'Cal', 'Dee', 'Eli', 'Fay', 'Gus', 'Ivy', 'Jon', 'Kim']
# ---------------------------------------------------------------- levels
def L_add(r):
    def t1(): a, b = r.randrange(11, 60), r.randrange(2, 10); return item(f"What is {a} plus {b}?", a + b, near(a + b, r), [f"Start at {a}. Count up {b}.", f"{a} plus {b} is {a + b}."], f"{a}+{b}")
    def t2(): a, b = r.randrange(20, 80), r.randrange(2, 10); return item(f"What is {a} minus {b}?", a - b, near(a - b, r), [f"Start at {a}. Count back {b}.", f"{a} minus {b} is {a - b}."], f"{a}-{b}")
    def t3(): a, b = r.randrange(2, 9) * 10, r.randrange(1, 9) * 10; return item(f"What is {a} plus {b}?", a + b, near(a + b, r), [f"Think in tens: {a // 10} tens plus {b // 10} tens is {(a + b) // 10} tens.", f"That is {a + b}."], f"{a}+{b}")
    def t4(): a, b = r.randrange(5, 30), r.randrange(3, 15); n = r.choice(NM); return item(f"{n} has ${a}. {n} earns ${b} more. How many dollars does {n} have now?", a + b, near(a + b, r), ["Earns more means add.", f"{a} plus {b} is {a + b}. So {a + b} dollars."], f"{a}+{b}", kind='money')
    def t5(): a, b = r.randrange(15, 40), r.randrange(3, 12); return item(f"You have {a} dollars. You spend {b}. How many dollars are left?", a - b, near(a - b, r), ["Spend means take away. Left means subtract.", f"{a} minus {b} is {a - b}."], f"{a}-{b}", kind='money')
    def t6(): a, b, c = r.randrange(2, 10), r.randrange(2, 10), r.randrange(2, 10); return item(f"Add {a}, {b}, and {c}.", a + b + c, near(a + b + c, r), [f"First {a} plus {b} is {a + b}.", f"Then {a + b} plus {c} is {a + b + c}."], f"{a}+{b}+{c}")
    def t7(): a = r.randrange(2, 9) * 10 + r.randrange(1, 9); b = 10 - a % 10; return item(f"What do you add to {a} to make {a + b}?", b, near(b, r), [f"Count up from {a} to {a + b}.", f"That is {b} steps. So {b}."], f"{a + b}-{a}")
    def t8(): a, b = r.randrange(40, 99), r.randrange(11, 30); return item(f"What is {a} minus {b}?", a - b, near(a - b, r), [f"Take away the tens first: {a} minus {b // 10 * 10} is {a - b // 10 * 10}.", f"Then take away {b % 10}: that is {a - b}."] if b % 10 else [f"{a} minus {b} is {a - b}."], f"{a}-{b}")
    return [t1, t2, t3, t4, t5, t6, t7, t8, t1, t5]
def L_times(r):
    def t1(): a, b = r.randrange(2, 13), r.randrange(2, 10); return item(f"What is {a} times {b}?", a * b, near(a * b, r), [f"{a} times {b} means {b} groups of {a}.", f"That is {a * b}."], f"{a}*{b}")
    def t2(): a, b = r.randrange(2, 10), r.randrange(2, 10); return item(f"What is {a * b} divided by {a}?", b, near(b, r), [f"Ask: {a} times what is {a * b}?", f"{a} times {b} is {a * b}. So the answer is {b}."], f"{a * b}/{a}")
    def t3(): a, b = r.randrange(3, 9), r.randrange(4, 13); return item(f"There are {a} packs. Each pack has {b} bottles. How many bottles in all?", a * b, near(a * b, r), ["Same size groups means multiply.", f"{a} times {b} is {a * b}."], f"{a}*{b}")
    def t4(): a, b = r.randrange(2, 7), r.randrange(3, 10); return item(f"{a * b} cookies are shared by {a} people. How many does each person get?", b, near(b, r), ["Shared equally means divide.", f"{a * b} divided by {a} is {b}."], f"{a * b}/{a}")
    def t5(): a = r.randrange(6, 30); return item(f"What is double {a}?", 2 * a, near(2 * a, r), ["Double means times 2.", f"{a} plus {a} is {2 * a}."], f"2*{a}")
    def t6(): a = r.randrange(3, 25) * 2; return item(f"What is half of {a}?", a // 2, near(a // 2, r), ["Half means split into 2 equal parts.", f"{a} divided by 2 is {a // 2}."], f"{a}/2")
    def t7(): a, b = r.randrange(2, 10), r.randrange(2, 10) * 10; return item(f"What is {a} times {b}?", a * b, near(a * b, r), [f"Do {a} times {b // 10} first. That is {a * b // 10}.", f"Then add a zero: {a * b}."], f"{a}*{b}")
    def t8(): a = r.randrange(2, 10); b = r.randrange(2, 7); return item(f"A ticket costs {a} dollars. How much for {b} tickets?", a * b, near(a * b, r), ["Each one costs the same, so multiply.", f"{a} times {b} is {a * b} dollars."], f"{a}*{b}", kind='money')
    return [t1, t2, t3, t4, t5, t6, t7, t8, t1, t2]
def L_neg(r):
    def t1(): a, b = r.randrange(2, 9), r.randrange(3, 12); return item(f"What is negative {a} plus {b}?", -a + b, near(-a + b, r, pos=False), [f"Picture a number line. Start at negative {a}.", f"Move {b} steps up. You land on {-a + b}." if b != a else "You land on 0."], f"-{a}+{b}", kind='num')
    def t2(): a, b = r.randrange(2, 8), r.randrange(9, 15); return item(f"What is {a} minus {b}?", a - b, near(a - b, r, pos=False), [f"Start at {a}. Go down {b} steps.", f"You pass zero. You land on {a - b}."], f"{a}-{b}")
    def t3(): a, b = r.randrange(2, 9), r.randrange(2, 9); return item(f"What is negative {a} minus {b}?", -a - b, near(-a - b, r, pos=False), [f"Start at negative {a}. Go down {b} more.", f"You land on {-a - b}."], f"-{a}-{b}")
    def t4(): a, b = r.randrange(2, 8), r.randrange(5, 15); return item(f"It is {a} degrees below zero. It warms up {b} degrees. What is the temperature now?", -a + b, near(-a + b, r, pos=False), [f"Below zero is negative {a}.", f"Negative {a} plus {b} is {-a + b}."], f"-{a}+{b}")
    def t5(): a, b = r.randrange(2, 7), r.randrange(2, 6); return item(f"What is negative {a} times {b}?", -a * b, near(-a * b, r, pos=False), ["A negative times a positive is negative.", f"{a} times {b} is {a * b}. So negative {a * b}."], f"-{a}*{b}")
    def t6(): a, b = r.randrange(2, 7), r.randrange(2, 6); return item(f"What is negative {a} times negative {b}?", a * b, near(a * b, r, pos=False), ["Two negatives multiplied make a positive.", f"{a} times {b} is {a * b}."], f"(-{a})*(-{b})")
    def t7(): a, b = r.randrange(2, 6), r.randrange(2, 6); return item(f"What is negative {a * b} divided by {a}?", -b, near(-b, r, pos=False), ["Negative divided by positive is negative.", f"{a * b} divided by {a} is {b}. So negative {b}."], f"-{a * b}/{a}")
    def t8(): a, b = r.randrange(10, 40), r.randrange(41, 80); return item(f"You have {a} dollars. You pay a bill of {b} dollars. What is your balance now?", a - b, near(a - b, r, pos=False), [f"{a} minus {b}.", f"You go below zero by {b - a}. So negative {b - a}."], f"{a}-{b}")
    return [t1, t2, t3, t4, t5, t6, t7, t8, t1, t2]
def L_fmean(r):
    def t1(): d = r.choice([3, 4, 6, 8]); n = r.randrange(1, d); return item(f"A pizza is cut into {d} equal slices. You eat {n}. What fraction of the pizza did you eat?", F(n, d), [F(d, n) if n > 1 else F(d + 1, d), F(d - n, d) if d - n != n else F(n, d + 1), F(n, d + 2)], [f"The bottom number is how many equal slices: {d}.", f"The top number is how many you ate: {n}.", f"So {fw(F(n, d))}. Written {n}/{d}."] if F(n, d).denominator == d else [f"Bottom number: {d} slices. Top number: {n} eaten.", f"{n}/{d}. That is the same as {fw(F(n, d))}."], R(n, d), kind='frac', say=f"A pizza is cut into {d} equal slices. You eat {n}. What fraction of the pizza did you eat?")
    def t2(): d = r.choice([4, 5, 6, 8, 10]); n = r.randrange(1, d); left = d - n; return item(f"A chocolate bar has {d} equal pieces. You eat {n}. What fraction is left?", F(left, d), [F(n, d) if n != left else F(n, d + 1), F(left, d + 1), F(1, d) if left != 1 else F(2, d)], [f"There were {d} pieces. You ate {n}. So {left} are left.", f"{left} out of {d} is {left}/{d}."], R(left, d), kind='frac')
    def t3(): d = r.choice([3, 4, 5, 6, 8]); n = r.randrange(1, d); return item(f"In the fraction {n}/{d}, how many equal parts is the whole cut into?", d, [n, d + n, d - 1 if d - 1 != n else d + 1], ["The bottom number tells how many equal parts the whole is cut into.", f"The bottom number is {d}."], f"{d}", say=f"In the fraction {fw(F(n, d)) if F(n, d).denominator == d else f'{n} over {d}'}, how many equal parts is the whole cut into?")
    def t4(): d = r.choice([3, 4, 5, 6, 8]); n = r.randrange(2, d) if d > 2 else 1; return item(f"In the fraction {n}/{d}, how many parts do you have?", n, [d, n + 1 if n + 1 != d else n + 2, d - n if d - n != n else d + 1], ["The top number tells how many parts you have.", f"The top number is {n}."], f"{n}")
    def t5(): d = r.choice([2, 3, 4, 5, 6, 8]); return item(f"A cake is cut into {d} equal pieces. How many pieces make the whole cake?", d, [d - 1, d + 1, 2 * d], [f"All {d} pieces together are the whole cake.", f"So {d} {DW[d][1]} make 1 whole."], f"{d}")
    def t6(): d = r.choice([5, 6, 8, 10]); n = r.randrange(1, d); return item(f"There are {d} sailors on a team. {n} are on watch. What fraction are on watch?", F(n, d), [F(d - n, d) if d - n != n else F(n, d + 1), F(n, d + 1), F(d, d + n)], [f"The whole team is {d}. That is the bottom.", f"{n} on watch is the top. So {n}/{d}" + (f", which is {fw(F(n, d))}." if F(n, d).denominator != d else ".")], R(n, d), kind='frac')
    def t7(): d = r.choice([3, 4, 5]); return item(f"A pie is cut into {d} equal slices. You eat all of them. What fraction did you eat? Say it as a number.", 1, [F(1, d), F(d - 1, d), d], [f"{d} out of {d} is the whole pie.", f"{d}/{d} is 1."], "1")
    return [t1, t2, t3, t4, t5, t6, t7, t1, t2, t6]
def L_halves(r):
    def t1(): a = r.randrange(2, 20) * 2; return item(f"What is half of {a}?", a // 2, near(a // 2, r), ["Half means 2 equal parts.", f"{a} divided by 2 is {a // 2}."], f"{a}/2")
    def t2(): a = r.randrange(2, 10) * 4; return item(f"What is a quarter of {a}?", a // 4, near(a // 4, r), ["A quarter means 4 equal parts. Take one part.", f"{a} divided by 4 is {a // 4}."], f"{a}/4")
    def t3(): return item("How many quarters make one whole?", 4, [2, 3, 5], ["Picture a pizza cut into 4 slices. Each slice is a quarter.", "All 4 slices make the whole pizza. So 4."], "4")
    def t4(): return item("Two quarters is the same as what fraction?", F(1, 2), [F(1, 3), F(1, 4), F(3, 4)], ["Picture 4 slices. Take 2 of them.", "That is half the pizza. So one half."], R(2, 4), kind='frac')
    def t5(): k = r.randrange(2, 6); return item(f"How many halves are in {k} whole pizzas?", 2 * k, [k, k + 2, 4 * k], ["Each pizza has 2 halves.", f"{k} pizzas times 2 is {2 * k} halves."], f"{k}*2")
    def t6(): return item("A quarter of an hour is how many minutes?", 15, [25, 30, 4], ["An hour is 60 minutes.", "A quarter is 60 divided by 4. That is 15 minutes."], "60/4")
    def t7(): return item("Half a dollar is how many cents?", 50, [25, 5, 20], ["A dollar is 100 cents.", "Half of 100 is 50."], "100/2")
    def t8(): a = r.randrange(2, 10) * 4; return item(f"What is three quarters of {a}?", a * 3 // 4, near(a * 3 // 4, r), [f"First find one quarter: {a} divided by 4 is {a // 4}.", f"Three quarters is 3 of those: {a // 4} times 3 is {a * 3 // 4}."], f"{a}*3/4")
    def t9(): return item("A quarter of a dollar is how many cents?", 25, [4, 20, 50], ["A dollar is 100 cents.", "100 divided by 4 is 25."], "100/4")
    def t10(): k = r.randrange(2, 5); return item(f"How many quarters are in {k} wholes?", 4 * k, [2 * k, k + 4, 4 * k + 1], ["Each whole has 4 quarters.", f"{k} times 4 is {4 * k}."], f"{k}*4")
    return [t1, t2, t3, t4, t5, t6, t7, t8, t9, t10]
def L_equiv(r):
    def t1(): n, d = r.choice([(1, 2), (1, 3), (2, 3), (1, 4), (3, 4), (2, 5)]); k = r.choice([2, 3, 4]); return item(f"{n}/{d} is the same as how many {DW[d * k][1] if d * k in DW else 'parts out of ' + str(d * k)}?", n * k, [n + k, n * k + 1, d * k - n * k if d * k - n * k != n * k else n * k + 2], [f"The bottom went from {d} to {d * k}. That is times {k}.", f"Do the same to the top: {n} times {k} is {n * k}."], f"{n}*{k}", say=f"{fw(F(n, d))} is the same as how many {DW[d * k][1] if d * k in DW else str(d * k) + 'ths'}?") if d * k in DW else t1()
    def t2(): n, d = r.choice([(1, 2), (1, 3), (2, 3), (3, 4), (1, 5)]); k = r.choice([2, 3]); return item(f"Fill in the blank: {n}/{d} = blank over {d * k}.", n * k, [n + k, d, n * k + 1], [f"{d} times {k} is {d * k}.", f"So multiply the top by {k} too: {n * k}."], f"{n}*{k}")
    def t3(): k = r.choice([2, 3, 4, 5]); return item(f"Fill in the blank: 1/2 = {k}/blank.", 2 * k, [k + 2, k + 1, 4 * k], [f"The top went from 1 to {k}. That is times {k}.", f"Do the same to the bottom: 2 times {k} is {2 * k}."], f"2*{k}")
    def t4(): return item("Picture a pizza cut into 8 slices. How many slices make one half?", 4, [2, 6, 8], ["Half of 8 slices is 4 slices.", "So 4/8 is the same as one half."], "8/2")
    def t5(): d = r.choice([6, 9, 12]); return item(f"How many {DW[d][1]} make one third?", d // 3, [d // 2, 3, d // 3 + 1], [f"Split {d} parts into 3 equal groups.", f"{d} divided by 3 is {d // 3}."], f"{d}/3")
    def t6(): d = r.choice([8, 12]); return item(f"How many {DW[d][1]} make three fourths?", d * 3 // 4, [3, d // 4, d * 3 // 4 + 1], [f"One fourth of {d} is {d // 4}.", f"Three fourths is 3 times that: {d * 3 // 4}."], f"{d}*3/4")
    return [t1, t2, t3, t4, t5, t6, t1, t2, t3, t5]
def L_simplify(r):
    def t1(): n, d = r.choice([(1, 2), (1, 3), (2, 3), (1, 4), (3, 4), (2, 5), (3, 5), (1, 5)]); k = r.choice([2, 3, 4]); N, D = n * k, d * k; return item(f"Simplify {N}/{D}.", F(n, d), [F(N, D * 2), F(n + 1, d + 1) if F(n + 1, d + 1) != F(n, d) else F(n, d + 2), F(d, n)], [f"Find a number that goes into both {N} and {D}. {k} works.", f"{N} divided by {k} is {n}. {D} divided by {k} is {d}.", f"So {fw(F(n, d))}."], R(N, D), kind='frac', form='simplest')
    def t2(): k = r.choice([2, 3, 5]); return item(f"Simplify {k}/{2 * k}.", F(1, 2), [F(1, 3), F(2, 3), F(1, 4)], [f"{k} is half of {2 * k}.", "So it is one half."], R(k, 2 * k), kind='frac', form='simplest')
    def t3(): d = r.choice([3, 4, 5, 6, 8]); return item(f"Simplify {d}/{d}.", 1, [F(1, d), d, 0], [f"{d} out of {d} is all of it.", "That is 1 whole."], R(d, d), form='simplest')
    def t4(): N, D = r.choice([(6, 8), (6, 9), (4, 6), (10, 15), (8, 12), (9, 12)]); v = F(N, D); g = N // v.numerator; return item(f"Simplify {N}/{D}.", v, [F(N // 2, D // 2) if N % 2 == 0 and D % 2 == 0 and F(N // 2, D // 2) != v and (N//2)/(D//2) else F(v.numerator + 1, v.denominator), F(v.denominator, v.numerator), F(N - 1, D)], [f"{g} goes into both {N} and {D}.", f"{N} divided by {g} is {v.numerator}. {D} divided by {g} is {v.denominator}.", f"So {fw(v)}."], R(N, D), kind='frac', form='simplest')
    def t5(): N, D = r.choice([(2, 10), (5, 10), (4, 10), (6, 10), (8, 10)]); v = F(N, D); return item(f"Simplify {N}/{D}.", v, [F(v.numerator + 1, v.denominator), F(1, D), F(v.denominator, v.numerator) if v.numerator != 1 else F(2, 10 // 2 + 1)], ["Both numbers can be divided by 2." if N % 2 == 0 else "", f"So {fw(v)}."], R(N, D), kind='frac', form='simplest')
    return [t1, t2, t3, t4, t5, t1, t4, t1, t4, t5]
def L_compare(r):
    def pair(a, b, big=True):
        ans = max(a, b) if big else min(a, b); other = min(a, b) if big else max(a, b)
        return ans, [other, F(1, 1) if ans != 1 and other != 1 else F(2, 1), F(ans.numerator, ans.denominator + 1) if F(ans.numerator, ans.denominator + 1) not in (ans, other) else F(3, 7)]
    def t1(): d1, d2 = r.sample([2, 3, 4, 5, 6, 8], 2); a, b = F(1, d1), F(1, d2); ans, w = pair(a, b); return item(f"Which is bigger: 1/{d1} or 1/{d2}?", ans, w, ["Picture two pizzas, the same size.", f"One is cut into {d1} slices. One into {d2}. More slices means smaller slices.", f"So {fw(ans)} is bigger."], f"Max({R(1, d1)},{R(1, d2)})", kind='frac', say=f"Which is bigger: {fw(a)} or {fw(b)}?")
    def t2(): d = r.choice([5, 6, 8, 10]); n1, n2 = r.sample(range(1, d), 2); a, b = F(n1, d), F(n2, d); ans, w = pair(a, b); return item(f"Which is bigger: {n1}/{d} or {n2}/{d}?", ans, w, [f"The bottoms are the same, {d}. So the slices are the same size.", "More slices is more.", f"So {fs(ans)} is bigger."], f"Max({R(n1, d)},{R(n2, d)})", kind='frac', say=f"Which is bigger: {n1} {DW[d][1] if n1 > 1 else DW[d][0]} or {n2} {DW[d][1] if n2 > 1 else DW[d][0]}?")
    def t3(): a, b = r.choice([(F(1, 2), F(1, 3)), (F(3, 4), F(2, 3)), (F(1, 2), F(2, 5)), (F(2, 3), F(1, 2)), (F(3, 4), F(1, 2)), (F(3, 5), F(1, 2))]); ans, w = pair(a, b); n = a.denominator * b.denominator; return item(f"Which is bigger: {fs(a)} or {fs(b)}?", ans, w, [f"Give them the same bottom, {n}.", f"{fs(a)} is {a.numerator * b.denominator}/{n}. {fs(b)} is {b.numerator * a.denominator}/{n}.", f"So {fw(ans)} is bigger."], f"Max({R(a.numerator, a.denominator)},{R(b.numerator, b.denominator)})", kind='frac')
    def t4(): d1, d2 = r.sample([2, 3, 4, 5, 8], 2); a, b = F(1, d1), F(1, d2); ans, w = pair(a, b, big=False); return item(f"Which is smaller: 1/{d1} or 1/{d2}?", ans, w, ["More slices means each slice is smaller.", f"So {fw(ans)} is smaller."], f"Min({R(1, d1)},{R(1, d2)})", kind='frac')
    def t5(): a = r.choice([F(1, 2), F(3, 4), F(2, 3), F(1, 4)]); b = F(1); ans, w = pair(a, b); return item(f"Which is bigger: {fs(a)} or 1?", ans, w, [f"{fw(a)} is less than a whole.", "So 1 is bigger."], f"Max({R(a.numerator, a.denominator)},1)", kind='frac')
    return [t1, t2, t3, t4, t5, t1, t2, t3, t3, t1]
def L_addsame(r):
    def t1(): d = r.choice([5, 7, 8, 9, 10]); a = r.randrange(1, d - 1); b = r.randrange(1, d - a); v = F(a + b, d); return item(f"What is {a}/{d} plus {b}/{d}?", v, [F(a + b, 2 * d), F(a * b, d) if F(a * b, d) != v else F(a + b + 1, d), F(a + b + 1, d)], [f"The bottoms are the same: {d}. Keep the bottom.", f"Add the tops: {a} plus {b} is {a + b}.", f"{a + b}/{d}" + (f", which simplifies to {fw(v)}." if v.denominator != d else ".")], f"{R(a, d)}+{R(b, d)}", kind='frac')
    def t2(): d = r.choice([5, 7, 8, 9, 10]); a = r.randrange(3, d); b = r.randrange(1, a); v = F(a - b, d); return item(f"What is {a}/{d} minus {b}/{d}?", v, [F(a + b, d) if F(a + b, d) != v else F(a, d), F(a - b, 2 * d) if F(a - b, 2 * d) != v else F(1, 2 * d), F(a - b + 1, d)], [f"Same bottom: {d}. Keep it.", f"Subtract the tops: {a} minus {b} is {a - b}.", f"{a - b}/{d}" + (f", which simplifies to {fw(v)}." if v.denominator != d else ".")], f"{R(a, d)}-{R(b, d)}", kind='frac')
