 ('Adding and Subtracting in Your Head', L_add, ['adding', 'subtracting', 'add and subtract', 'addition', 'subtraction', 'place value']),
 ('Times and Divide', L_times, ['times tables', 'multiplication', 'multiply', 'division', 'divide', 'times']),
 ('Negative Numbers', L_neg, ['negative numbers', 'negatives', 'negative']),
 ('What a Fraction Means', L_fmean, ['what fractions are', 'fractions', 'fraction meaning', 'what a fraction means', 'fractions one']),
 ('Halves and Quarters', L_halves, ['halves and quarters', 'halves', 'quarters', 'half']),
 ('Same Fraction, Different Names', L_equiv, ['equivalent fractions', 'equivalent', 'same fraction']),
 ('Simplifying Fractions', L_simplify, ['simplifying fractions', 'simplify', 'simplifying', 'reduce fractions']),
